INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (196, 'getModeloVersao', 'Retorna o snapshot completo de uma versao para visualizacao. Param: versaoId.', 'SQL', 'SELECT ID, NUMERO, CRIADO_EM, SNAPSHOT FROM DRIVER_VERSAO WHERE ID = {{versaoId}}', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
